require_once __DIR__.'/../auth_check.php';AccessManager::requirePageAccess();
require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../controllers/RhScheduleController.php';require_once __DIR__.'/../vendor/tecnickcom/tcpdf/tcpdf.php';
$personnelId=max(0,(int)($_GET['personnel_id']??0));if($personnelId<1){http_response_code(422);exit('Sélectionnez un collaborateur.');}
$service=(new RhScheduleController(Database::getConnection()))->service();$person=$service->getPersonnelScheduleContext($personnelId);if(!$person){http_response_code(404);exit('Collaborateur introuvable.');}$windows=$service->getPersonnelWorkWindows($personnelId);$days=[1=>'Lundi',2=>'Mardi',3=>'Mercredi',4=>'Jeudi',5=>'Vendredi',6=>'Samedi',7=>'Dimanche'];
$pdf=new TCPDF('L','mm','A4',true,'UTF-8',false);$pdf->setPrintHeader(false);$pdf->setPrintFooter(false);$pdf->SetMargins(10,10,10);$pdf->AddPage();$pdf->SetFillColor(15,23,42);$pdf->SetTextColor(255);$pdf->SetFont('helvetica','B',18);$pdf->Cell(0,16,'FINÉA · EMPLOI DU TEMPS HEBDOMADAIRE',0,1,'L',true);$pdf->SetTextColor(15,23,42);$pdf->SetFont('helvetica','B',12);$pdf->Cell(0,9,(string)($person['nom']??$person['full_name']??'Collaborateur'),0,1);$html='<table border="1" cellpadding="5"><thead><tr style="background-color:#fabe02;font-weight:bold"><th width="10%">Heures</th>';foreach($days as $d)$html.='<th width="12.85%">'.$d.'</th>';$html.='</tr></thead><tbody>';
for($hour=6;$hour<21;$hour++){$html.='<tr><td style="font-weight:bold;background-color:#f1f5f9">'.sprintf('%02d:00',$hour).'</td>';foreach($days as $i=>$d){$w=$windows[$i]??[];$start=substr((string)($w['start_time']??''),0,5);$end=substr((string)($w['end_time']??''),0,5);$slot=sprintf('%02d:00',$hour);$active=!empty($w['enabled'])&&$start!==''&&$end!==''&&$slot>=$start&&$slot<$end;$label=$active&&$slot===$start?htmlspecialchars($start.' – '.$end):($active?'●':'');$html.='<td align="center" style="'.($active?'background-color:#dcfce7;color:#047857':'color:#cbd5e1').'">'.$label.'</td>';}$html.='</tr>';}$html.='</tbody></table>';$pdf->writeHTML($html,true,false,true,false,'');$pdf->Output('emploi_du_temps_hebdomadaire_'.$personnelId.'.pdf','D');
